/**
 * TASK: Recognise keyboard chords such as Ctrl+Shift+S.
 *
 * Modifier state travels with the event: e.getModifiersEx() returns a set of
 * bits, and you test one with & against a mask, for example
 *
 *     boolean ctrl = (e.getModifiersEx() & KeyEvent.CTRL_DOWN_MASK) != 0;
 *
 * Register a KeyListener whose keyPressed builds the chord name:
 *   "Ctrl+" first when Control is held, then "Shift+" when Shift is held,
 *   then the key itself as KeyEvent.getKeyText(e.getKeyCode()).
 * So Control and Shift with the S key gives "Ctrl+Shift+S", and the plain
 * A key gives "A".
 *
 * Store that as the last chord, and count the chords that used at least one
 * modifier in modifierChordCount().
 *
 * EDGE CASE: pressing a modifier on its own fires keyPressed too, with the
 * key code VK_SHIFT or VK_CONTROL. Ignore those events completely -- they
 * must not change the last chord or any count.
 *
 * lastChord() is "none" until the first real chord arrives.
 *
 * No window is ever opened -- the tests build KeyEvents by hand and hand
 * them straight to the registered listener.
 */
import javax.swing.JPanel;

