import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;

public class ChordDetectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void press(ChordDetector panel, int modifiers, int keyCode) {
        KeyEvent event = new KeyEvent(panel, KeyEvent.KEY_PRESSED,
                System.currentTimeMillis(), modifiers, keyCode, KeyEvent.CHAR_UNDEFINED);
        for (KeyListener listener : panel.getKeyListeners()) {
            listener.keyPressed(event);
        }
    }

    public static void main(String[] args) {
        try {
            ChordDetector panel = new ChordDetector();
            check("a KeyListener is registered", true, panel.getKeyListeners().length >= 1);
            check("no chord yet", "none", panel.lastChord());
            check("no modifier chords yet", 0, panel.modifierChordCount());

            press(panel, KeyEvent.CTRL_DOWN_MASK, KeyEvent.VK_S);
            check("control with S", "Ctrl+S", panel.lastChord());
            check("counted as a modifier chord", 1, panel.modifierChordCount());

            press(panel, KeyEvent.CTRL_DOWN_MASK | KeyEvent.SHIFT_DOWN_MASK, KeyEvent.VK_S);
            check("control and shift with S", "Ctrl+Shift+S", panel.lastChord());

            press(panel, KeyEvent.SHIFT_DOWN_MASK, KeyEvent.VK_7);
            check("shift alone", "Shift+7", panel.lastChord());
            check("three modifier chords", 3, panel.modifierChordCount());

            press(panel, 0, KeyEvent.VK_A);
            check("a plain key has no prefix", "A", panel.lastChord());
            check("a plain key is not a modifier chord", 3, panel.modifierChordCount());

            press(panel, KeyEvent.SHIFT_DOWN_MASK, KeyEvent.VK_SHIFT);
            press(panel, KeyEvent.CTRL_DOWN_MASK, KeyEvent.VK_CONTROL);
            check("modifier keys alone are ignored", "A", panel.lastChord());
            check("and they are not counted", 3, panel.modifierChordCount());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

