import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import javax.swing.JPanel;

public class ChordDetector extends JPanel {

    private String lastChord = "none";
    private int modifierChords = 0;

    public ChordDetector() {
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                int code = e.getKeyCode();
                if (code == KeyEvent.VK_SHIFT || code == KeyEvent.VK_CONTROL) {
                    return;
                }
                boolean ctrl = (e.getModifiersEx() & KeyEvent.CTRL_DOWN_MASK) != 0;
                boolean shift = (e.getModifiersEx() & KeyEvent.SHIFT_DOWN_MASK) != 0;
                String chord = "";
                if (ctrl) {
                    chord = chord + "Ctrl+";
                }
                if (shift) {
                    chord = chord + "Shift+";
                }
                chord = chord + KeyEvent.getKeyText(code);
                lastChord = chord;
                if (ctrl || shift) {
                    modifierChords++;
                }
            }
        });
    }

    public String lastChord() {
        return lastChord;
    }

    public int modifierChordCount() {
        return modifierChords;
    }
}
